import { ChangeDetectorRef, Component, ElementRef, EventEmitter, NgZone, Output, Renderer2, ViewChild } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { CommonModule } from '@angular/common';
import { MatTooltipModule } from '@angular/material/tooltip';
import { MatExpansionModule } from '@angular/material/expansion';
import { MatMenuModule } from '@angular/material/menu';
import { BadgeComponent } from '../../../shared/components/badge/badge.component';
import { FactTableComponent } from '../../../shared/components/fact-table/fact-table.component';
import { ContactFormComponent } from '../../../shared/components/contacts/contact-form/contact-form.component';
import { EmptyComponent } from '../../../shared/components/empty/empty.component';
import { ContactdetailComponent } from '../../../shared/components/contacts/contactdetail/contactdetail.component';
import { TableComponent } from '../../../shared/components/myfiles/table/table.component';
import { FilehaderComponent } from '../../../shared/components/myfiles/filehader/filehader.component';
import { AvatarComponent } from '../../../shared/components/avatar/avatar.component';
import { IconComponent } from '../../../shared/components/icon/icon.component';
import { ButtonComponent } from '../../../shared/components/button/button.component';
import { HeaderService } from '../../../core/services/header/header.service';
import { CasedetailService } from '../../../shared/services/casedetail/casedetail.service';
import { MyfileService } from '../../../shared/services/myfile/myfile.service';
import { ContactService } from '../../../shared/services/contact/contact.service';
import { WorkspaceService } from '../../services/workspace/workspace.service';
import { FactfileRes, factissuelistRes, factlistRes, IssuecategoryRes } from '../../interfaces/workspace.interface';
import { RecentfileComponent } from '../../../shared/components/recentfile/recentfile.component';
import { bundleDetailRes } from '../../../shared/interfaces/myfile.interface';
import { PreviewComponent } from '../../../shared/components/myfiles/preview/preview.component';
import { myTeamUsers, toolEvents } from '../../../pdf/interfaces/pdf.interface';
import { CommonService } from '../../../shared/services/common/common.service';
import { FiltersComponent } from '../../../shared/components/filters/filters.component';
import { finalFilterList } from '../../../shared/interfaces/filter.interface';
import { SkeletonComponent } from '../../../shared/components/skeleton/skeleton.component';
import { FilecolumnService } from '../../../shared/services/filecolumn/filecolumn.service';
import { FormsModule } from '@angular/forms';
import { UserPermissionService } from '../../../shared/services/user-permission/user-permission.service';
import { CommonfunctionService } from '../../../core/utility/commonfunction.service';

@Component({
  selector: 'app-factcontact',
  standalone: true,
  imports: [CommonModule, IconComponent, ButtonComponent, MatTooltipModule, MatExpansionModule, BadgeComponent, FactTableComponent,
    MatMenuModule, AvatarComponent, FilehaderComponent, TableComponent, ContactdetailComponent, EmptyComponent, ContactFormComponent,
    RecentfileComponent, PreviewComponent, FiltersComponent, SkeletonComponent, FormsModule],
  templateUrl: './factcontact.component.html',
  styleUrl: './factcontact.component.scss'
})
export class FactcontactComponent {
  cPermission: any = 'N';
  private startX: number;
  private startWidth: number;
  private animationFrameId: number;
  leftWidth: number = 300; // Set an initial pixel width for the left panel

  @ViewChild('parent') parent: ElementRef;

  nCaseid: string;
  nSectionid: string = null;
  nContactid: string;
  editable_list: any;
  isNew: boolean = false;
  loading: boolean = true;
  isDetail: boolean = false;

  viewtype: any = [
    { tab: 'F', 'cName': 'Fact Contacts' },
    { tab: 'C', 'cName': 'File Contacts' },
  ];

  viewlist: bundleDetailRes[] = [];
  isPreview: boolean = false;


  activetab = 'F';
  showcolalert: boolean = false;

  tablecols: any = [
    {
      id: 1,
      'name': 'Date/Time',
      'key': 'Date/Time',
      'isshow': true,
    },
    {
      id: 2,
      'name': 'Type',
      'key': 'Type',
      'isshow': true,
    },
    {
      id: 4,
      'name': 'Fact Box',
      'key': 'Fact Box',
      'isshow': true,
    },
    {
      id: 9,
      'name': 'Relevance',
      'key': 'Relevance',
      'isshow': false,
    },
    {
      id: 10,
      'name': 'Impact',
      'key': 'Impact',
      'isshow': false,
    },
    {
      id: 11,
      'name': 'Source',
      'key': 'Source',
      'isshow': false,
    }
  ];
  Contact: any = [];
  fileContact: any = [];
  List: any = []
  reqcols: any = {};
  userList: myTeamUsers[] = [];


  isFiltered: boolean = false;
  showfilter: boolean = false;
  jFilter: finalFilterList[] = [];

  isadmin: boolean = false;
  filtercount: number = 0;
  cSearch: string = '';
  reqcolKeys = []
  currentContact: any;
  constructor(private hs: HeaderService, private cDetailS: CasedetailService, private route: ActivatedRoute,
    private renderer: Renderer2, private zone: NgZone, private mfs: MyfileService, private common: CommonService,
    private wsService: WorkspaceService,
    private cdr: ChangeDetectorRef,
    private CService: ContactService,
    private fcs: FilecolumnService,
    private userPermissions: UserPermissionService, private cf: CommonfunctionService) {

    var params = this.route.snapshot.params;
    params = JSON.parse(atob(params["id"]));
    this.nCaseid = params && params["id"] ? params["id"] : 0;
    this.reqcols = this.fcs.reqcols;


    if (this.reqcols) {
      this.reqcols['extra']['view'] = false;
      this.reqcols['check']['view'] = false;
    }

    userPermissions.userPermissionList(this.nCaseid);

  }

  async ngOnInit() {
    this.hs.nCaseid = this.nCaseid;
    this.hs.Casedetail = await this.cDetailS.getCaseInfo(this.nCaseid);


    this.tablecols = !this.isadmin ? this.fcs.tablecols.filter(e => e.key != 'remark') :
      this.fcs.tablecols.filter(e => e.key != 'relevence' && e.key != 'link' && e.key != 'impact' && e.key != 'remark');
    let totalwidth = window.screen.availWidth - 438;
    this.leftWidth = totalwidth;
    if (this.parent) {
      this.parent.nativeElement.style.setProperty('--folderswidth', `${totalwidth}px`);
    }
    this.getContactlist();
    // this.getteam_list();

    Object.fromEntries(
      Object.entries(this.fcs.reqcols).filter(([key]) => {
        let cols = this.tablecols.find(e => e.key.toLocaleLowerCase() == key)
        if (cols) {
          this.fcs.reqcols[key]["id"] = cols?.id;
          this.fcs.reqcols[key]["view"] = cols?.isshow;
          this.fcs.reqcols[key]["name"] = cols?.name;
          this.fcs.reqcols[key]["class"] = cols?.class;
          this.fcs.reqcols[key]["sortKey"] = cols?.sortKey;
          this.fcs.reqcols[key]["isEdit"] = cols?.isEdit;
          this.fcs.reqcols[key]["size"] = cols?.size;
        }
      })
    )
    this.reqcols = !this.isadmin ? this.fcs.reqcols : Object.fromEntries(
      Object.entries(this.fcs.reqcols).filter(([key]) => key !== 'relevence' && key !== 'link' && key !== 'impact')
    )
    this.reqcolKeys = Object.keys(this.reqcols);
    this.reqcolKeys = this.fcs.customSort(this.reqcols)

    this.cdr.detectChanges()
  }


  async getteam_list() {
    this.userList = await this.common.getMyTeamUsers(this.nCaseid);
  }

  async getContactlist() {

    let res = await this.wsService.getContactlist(this.nCaseid, []);
    this.loading = false;
    this.Contact = res;
    this.cdr.detectChanges();
  }

  async getFileContactlist() {
    let res = await this.CService.getFileContactlist(this.nCaseid, this.jFilter, this.cSearch);
    this.fileContact = res;
    this.cdr.detectChanges();
  }

  async getContactFiles(contact) {
    this.currentContact = contact;
    let res = await this.CService.getContactFiles(contact.nContactid, null, this.cSearch, this.nCaseid);
    contact["tablelist"] = res;
    this.isDetail = true;
    this.nContactid = contact.nContactid;
    this.cdr.detectChanges();
  }

  changeTable(event: any, x) {
    if (event == 'VIEW') {
      this.isDetail = false;
      this.isNew = false;
      this.viewFile(x);
      this.resetresize();

    }
  }

  changeTab(x) {
    if (this.activetab == x.tab) { return; }
    this.activetab = x.tab;
    this.isFiltered = false;
    this.jFilter = [];
    if (x.tab == 'C') {
      this.getFileContactlist();

      setTimeout(() => {
        let totalwidth = window.screen.availWidth - 438;
        this.leftWidth = totalwidth;
        if (this.parent) {
          this.parent.nativeElement.style.setProperty('--folderswidth', `${totalwidth}px`);
        }
      }, 100);

    }
  }


  OnFilterResult(e: toolEvents) {

    if (e.event == 'FILTER') {
      this.jFilter = e.data;
      this.isFiltered = e.data?.length;
      this.getFileContactlist();
      this.cdr.detectChanges();
    }
    else if (e.event == 'Count') {
      this.filtercount = e.data;
      this.cdr.detectChanges();
    }
    else if (e.event == 'BACK') {
      this.showfilter = false;
      this.cdr.detectChanges();
    }
  }

  // changeTabcols(x) {
  //   x.isshow = !x.isshow;
  //   if (this.tablecols.filter(x => x.isshow == true).length >= 3) {
  //     this.showcolalert = false;
  //   } else {
  //     this.showcolalert = true;
  //   }
  // }

  async outputEvent(event: any) {
      this.cPermission = 'N';
    if (event.event == 'EDIT') {
      this.nContactid = event.data.nContactid;
      let edit_detail = await this.CService.getContactDetail(event.data.nContactid);
      this.cPermission = 'E';
      this.editable_list = edit_detail;
      this.isDetail = false;
      this.isNew = true;
    }
    if (event.event == 'NEW') {
      this.isNew = true;
    } if (event.event == 'CLOSE') {
      this.isDetail = false;
      this.isNew = false;
      this.cdr.detectChanges();
    }
    if (event.event == 'NEW_ADDED') {
      this.nContactid = event.data.nContactid;
      this.getContactlist();
      this.getFileContactlist();
      this.isNew = false;
      this.isDetail = true;
    }
    if (event.event == 'DELETE') {
      this.deleteContact(this.nContactid)
    }

  }

  // Resize code starts here

  initResize(event: MouseEvent): void {
    event.preventDefault();
    this.startX = event.clientX;
    this.startWidth = this.leftWidth;

    this.zone.runOutsideAngular(() => {
      window.addEventListener('mousemove', this.onMouseMove);
      window.addEventListener('mouseup', this.stopResize);
    });
  }


  isdraging: boolean = false;


  onMouseMove = (event: MouseEvent) => {
    cancelAnimationFrame(this.animationFrameId);
    this.animationFrameId = requestAnimationFrame(() => this.doResize(event));
  };

  doResize = (event: MouseEvent) => {
    this.isdraging = true;
    event.preventDefault();
    const width = Math.max(300, this.startWidth + (event.clientX - this.startX));
    this.leftWidth = width;
    this.parent.nativeElement.style.setProperty('--folderswidth', `${width}px`);
    this.renderer.setStyle(document.body, 'cursor', 'e-resize');
  };

  stopResize = () => {

    this.isdraging = false;

    if (this.animationFrameId) {
      cancelAnimationFrame(this.animationFrameId);
    }
    this.renderer.setStyle(document.body, 'cursor', 'auto');
    window.removeEventListener('mousemove', this.onMouseMove);
    window.removeEventListener('mouseup', this.stopResize);
  };



  async getFactlist(x, nContactid, nIssueid) {
    if (nContactid && x.factlist && x.factlist.length) { return; }
    if (!x.isopened) { return; }
    x.loading = true;
    let res: factlistRes[] = await this.wsService.getFactlist(this.nCaseid, nContactid, nIssueid, 'ALL', []);
    x.loading = false;
    x.factlist = res.filter(e => e.cFType == 'F')//this.groupIssueCategory(res);
    x.quickfactlist = res.filter(e => e.cFType == 'FQ')//this.groupIssueCategory(res);

    // Normalized note sort key so Note column sorting works consistently here as well
    const computeNoteSort = (f: factlistRes) => {
      const base = (f.cFact && f.cFact.trim().length)
        ? f.cFact
        : (Array.isArray(f.jTexts) && f.jTexts.length ? String(f.jTexts[0]) : '');
      f.noteSort = base || '';
    };
    x.factlist.forEach(computeNoteSort);
    x.quickfactlist.forEach(computeNoteSort);

    this.getIssuels(x, nContactid, nIssueid);
    this.getFactfile(x, nContactid, nIssueid);
  }

  async getIssuels(x, nContactid: string, nIssueid: string) {
    const res: factissuelistRes[] = await this.wsService.getFactIssuelist(this.nCaseid, nContactid, nIssueid, 'ALL', []);
    x.factlist.forEach(element => {
      let issues = res.filter(e => e.nFSid == element.nFSid);
      let issuescat: IssuecategoryRes[] = this.groupIssueCategory(issues);
      element.issues = issuescat;
      this.relavanceImpactFilter(element, issues);
    });
    this.cdr.detectChanges();
  }

  relavanceImpactFilter(fact, issues) {
    if (issues.length) {
      let max = issues.reduce((prev, current) => (prev.nRelevanceseq > current.nRelevanceseq) ? prev : current);
      fact.nRelevancecount = issues.filter(e => e.nRelevanceid == max.nRelevanceid).length;
      fact.cRelevance = max.cRelevance;
    }
    if (issues.length) {
      let max = issues.reduce((prev, current) => (prev.nImpactseq > current.nImpactseq) ? prev : current);
      fact.nImpactcount = issues.filter(e => e.nImpactid == max.nImpactid).length;
      fact.nImpactid = max.nImpactid;
    }
    // issues.forEach(element => {
    //   if (element.cRelevance == fact.cRelevance) {
    //     fact.nRelevancecount++;
    //   }
    //   if (element.nImpactid == fact.nImpactid) {
    //     fact.nImpactcount++;
    //   }
    // });
    return fact;

  }


  groupIssueCategory(issues) {
    let issuecategory: IssuecategoryRes[] = [];
    issues.forEach(element => {
      if (!issuecategory.length) {
        issuecategory.push({ nICid: element.nICid, cCategory: element.cCategory, sublist: [element] });
      } else {
        let index = issuecategory.findIndex(e => e.nICid == element.nICid);
        if (index > -1) {
          issuecategory[index].sublist.push(element);
        } else {
          issuecategory.push({ nICid: element.nICid, cCategory: element.cCategory, sublist: [element] });
        }
      }
    });
    return issuecategory;
  }

  async getFactfile(x, nContactid: string, nIssueid: string) {
    const res: FactfileRes[] = await this.wsService.getFactfilelist(this.nCaseid, nContactid, nIssueid, 'ALL', []);
    x.factlist.forEach(element => {
      let file: FactfileRes[] = res.filter(e => e.nFSid == element.nFSid);
      element.linkfile = file
    });
    this.cdr.detectChanges();
  }



  resetresize() {
    let totalwidth = window.screen.availWidth - 438;
    this.leftWidth = totalwidth;
    this.parent.nativeElement.style.setProperty('--folderswidth', `${totalwidth}px`);
  }

  recentOutput(event) {
    if (event.event == 'VIEW') {
      this.viewFile(event.data);
    }
  }

  // viewFile(x) {
  //   this.resetresize();
  //   if (!this.isPreview) {
  //     this.isPreview = !this.isPreview;
  //     this.activateItem(x);
  //   } else {
  //     this.updatePreviewMode(x);
  //   }
  // }

  viewFile(x) {
    if (!this.isPreview) {
      this.resetresize();
      this.isPreview = !this.isPreview;
      this.showfilter = false;
      this.activateItem(x);
    } else {
      this.updatePreviewMode(x);
    }
  }


  activateItem(x) {
    if (this.viewlist.length === 0 || this.viewlist[0].nBundledetailid !== x.nBundledetailid) {
      this.viewlist = [x];
      this.viewlist[0]["active"] = true;
    }
  }

  updatePreviewMode(x) {
    const index = this.viewlist.findIndex(e => e.nBundledetailid === x.nBundledetailid);
    if (index > -1) {
      this.viewlist.splice(index, 1);
    } else {
      this.activateItem(x);
      this.viewlist.forEach((item, idx) => item["active"] = (idx === 0));
    }
  }

  removeGroup(x) {
    x.isGrouping = false;
    x.groupinglist = [];

  }

  openFactLink(data) {
    if (!data.nBundledetailid) return;
    let page = 1
    if (data?.jLinktype?.pages && data?.jLinktype?.pages.length) {
      page = data?.jLinktype?.pages[0]
    } else if (data?.jLinktype?.start) {
      page = data?.jLinktype?.start;
    }
    this.cf.openHyperLinkFile(data.nBundledetailid, this.nCaseid, null, null, false, page, data.nFSid)
  }


  OnTableEvent(e, x) {
    if (e.event == 'EXTERNAL-FACT-SHEET') {
      this.openFactLink(e.data);
      return
    }



    if (e.event == 'SORT') {
      let col = e.data.col;
      let typ = e.data.col.typ == 'A' ? 'asc' : e.data.col.typ == 'D' ? 'desc' : 'G';
      if (typ == 'G') {
        x.isGrouping = true;
        x.groupinglist = [];
        if (col.clmn == 'R' || col.clmn == 'I') {
          for (let n of x.factlist) {
            var obj: any = {};
            var searchclm = '';
            if (col.clmn == 'R') {
              x.Groupby = 'Relevance';
              searchclm = 'nRelevanceid';

              for (let i of n.issues) {
                for (let issue of i.sublist) {
                  if (issue.nRelevanceid) {
                    obj = { id: issue.nRelevanceid, name: issue.cRelevance };
                    if (Object.keys(obj).length) {
                      var ins = x.groupinglist.findIndex(m => m.id == obj.id);
                      if (ins >= 0) {
                        if (x.groupinglist[ins]["factlist"].findIndex(m => m.nFSid == n.nFSid) == -1) {
                          x.groupinglist[ins]["factlist"].push(n);
                        }
                      } else {
                        x.groupinglist.push({ id: obj.id, name: obj.name, factlist: [n] });
                      }
                    }
                    // break;
                  }
                }
              }
            } else if (col.clmn == 'I') {
              x.Groupby = 'Impact';
              searchclm = 'nImpactid';
              for (let i of n.issues) {
                for (let issue of i.sublist) {
                  if (issue.nImpactid) {
                    obj = { id: issue.nImpactid, name: issue.cImpact };
                    if (Object.keys(obj).length) {
                      var ins = x.groupinglist.findIndex(m => m.id == obj.id);
                      if (ins >= 0) {
                        if (x.groupinglist[ins]["factlist"].findIndex(m => m.nFSid == n.nFSid) == -1) {
                          x.groupinglist[ins]["factlist"].push(n);
                        }
                      } else {
                        x.groupinglist.push({ id: obj.id, name: obj.name, factlist: [n] });
                      }
                    }
                    // break;
                  }
                }
              }
              // obj = n.nImpactid ? { id: n.nImpactid, name: n.cImpact, img: n.impactls[0]["cImpimg"] } : {};
            }
          }
        }
        else if (col.clmn == 'F') {
          x.Groupby = 'Level type';
          x.groupinglist = [{
            "id": 1,
            "name": "File level",
            "factlist": []
          }, {
            "id": 2,
            "name": "Text level",
            "factlist": []
          }, {
            "id": 3,
            "name": "Range level",
            "factlist": []
          }];
          for (let n of x.factlist) {
            try {
              if (n.jLinktype.type != 'F' && n.cType == 'M') {
                if (x.groupinglist[2]["factlist"].findIndex(m => m.nFSid == n.nFSid) == -1) {
                  x.groupinglist[2]["factlist"].push(n);
                }
              } else if (n.jLinktype?.type == 'F' && n.cType == 'M') {
                if (x.groupinglist[0]["factlist"].findIndex(m => m.nFSid == n.nFSid) == -1) {
                  x.groupinglist[0]["factlist"].push(n);
                }
              } else if (n.cType != 'M') {
                if (x.groupinglist[1]["factlist"].findIndex(m => m.nFSid == n.nFSid) == -1) {
                  x.groupinglist[1]["factlist"].push(n);
                }
              }
            } catch (error) { }
          }
        }
        if (!x.groupinglist.length) {
          x.groupFor = '';
          x.isGrouping = false;
        }
        if (col.clmn == 'F') {
          let isdata: boolean = false
          x.groupinglist.forEach(e => {
            if (e.factlist.length) {
              isdata = true
            }
          });
          x.isGrouping = isdata;
        }
        return;
      }
      let clmn = col.clmn == 'topimpact_ind' ? 'nImpactid' : col.clmn == 'toprelevance_ind' ? 'cRelevance' : col.clmn;
      x.factlist = x.factlist.sort((a, b) => {
        if (typeof a[clmn] == 'string') {
          if (typ == 'asc') {
            return a[clmn].localeCompare(b[clmn]);
          } else {
            return b[clmn].localeCompare(a[clmn]);
          }
        } else {
          if (typ == 'asc') {
            return a[clmn] - b[clmn];
          } else {
            return b[clmn] - a[clmn];
          }
        }
      });


    }
  }

  async deleteContact(nContactid) {
    if (this.fileContact.length) {
      try {

        let lsIndex = this.fileContact.findIndex(e => e.contactls.findIndex(m => m.nContactid == nContactid) > -1);
        if (lsIndex == -1) { return; }
        let index = this.fileContact[lsIndex].contactls.findIndex(e => e.nContactid == nContactid);
        if (index == -1) { return; }
        let contactls = this.fileContact[lsIndex]?.contactls || [];
        if (contactls.length) {
          let x = this.fileContact[lsIndex]?.contactls[index] || {};
          x.isopened = false;
          x.loading = false;

          const res = await this.CService.contactDelete({ nContactid: this.nContactid, permission: 'D' })
          // if (this.editable_list) {

          // }
          if (res.msg == 1) {

            this.isDetail = false;
            nContactid = null;
            contactls.splice(index, 1);
            this.cdr.detectChanges();
          }
        }
      } catch (error) {
        console.log(error);

      }

    }
  }


  checkId(x, shouldBeVisible) {
    const isRelevantId = (x.id === 8 && !this.fcs.collShow.includes(4)) || (x.id === 4 && !this.fcs.collShow.includes(8));
    const isCountConditionMet = this.fcs.collShow.length === 3;

    return (x.isshow === shouldBeVisible && isRelevantId) || isCountConditionMet;
  }


  changeTabcols(x) {
    if (x.isshow && (this.checkId(x, true) || (this.fcs.collShow.length == 3))) {
      if (this.fcs.collShow.length == 3) {
        this.showcolalert = true;
      } else {
        this.showcolalert = false;
      }
      return;
    }

    this.showcolalert = false;
    x.isshow = !x.isshow;
    for (const key in this.reqcols) {
      this.tablecols.forEach(e => {
        if (e.key.toLocaleLowerCase() == key.toLocaleLowerCase()) {
          this.reqcols[key]["view"] = e.isshow;
        }
      });
    }
    this.fcs.collShow = this.tablecols.filter(e => e.isshow).map(e => e.id);
    this.fcs.setCols();
  }

  searchContact(value: any) {
    const search = value?.trim();
    this.cSearch = search;

    if (value && value.trim().length > 0) {
      // Call when there is actual content (ignores only spaces)
      this.getFileContactlist();
    } else if (value === '') {
      // Call when user clears the input completely
      this.getFileContactlist();
    }

    this.cdr.detectChanges();
  }

  ngOnDestroy(): void {
    if (this.reqcols) {
      this.reqcols['check']['view'] = true;
    }
  }


}
